const out = [];
for (const item of $input.all()) {
  const lead = item.json;
  if (!['A', 'B'].includes(String(lead.priority || '').trim())) continue;
  if (String(lead.lead_status || '').trim() !== 'Validated') continue;
  if (!String(lead.decision_maker_name || '').trim()) continue;
  if (!String(lead.decision_maker_role || '').trim()) continue;
  if (String(lead.outreach_status || '').trim() !== 'Pending') continue;
  const channel = String(lead.email || '').trim() ? 'Email' : 'LinkedIn';
  out.push({ json: { ...lead, channel, language: 'es' } });
}
return out;

const crypto = require('crypto');
const lead = $('Filter Draft Candidates').item.json;
const response = $input.first().json;
const body = response.body || response;
let text = '';
if (Array.isArray(body.output)) for (const block of body.output) for (const content of (block.content || [])) if (content.type === 'output_text') text += content.text || '';
text = text || body.output_text || body.text || '';
let draft;
try { draft = JSON.parse(String(text)); } catch (error) { draft = null; }
if (!draft || !['LinkedIn', 'Email'].includes(draft.channel) || draft.language !== 'es') {
  const quote = String(lead.evidence_quote || lead.pain_summary || '').slice(0, 180);
  draft = { channel: lead.channel, language: 'es', subject: lead.channel === 'Email' ? `Consulta sobre flujos Grasshopper en ${lead.company_name}` : '', message: `Hola ${lead.decision_maker_name}, he visto la señal pública "${quote}". Es posible que en equipos con este tipo de flujo aparezcan picos de ejecución o preparación repetitiva de variantes. En AImetos ayudamos con ${lead.recommended_service}. ¿Tiene sentido que te envíe una idea concreta para revisarla?`, evidence_used: quote };
}
const words = String(draft.message || '').trim().split(/\s+/);
const limit = draft.channel === 'LinkedIn' ? 110 : 140;
if (words.length > limit) draft.message = words.slice(0, limit).join(' ');
return [{ json: { draft_id: 'draft_' + crypto.createHash('sha256').update(`${lead.lead_id}|${Date.now()}`).digest('hex').slice(0, 16), lead_id: lead.lead_id, company_name: lead.company_name, contact_name: lead.decision_maker_name, contact_role: lead.decision_maker_role, channel: draft.channel, language: 'es', subject: draft.subject || '', message: draft.message || '', evidence_used: draft.evidence_used || lead.evidence_quote || lead.source_url, status: 'Draft', generated_at: new Date().toISOString(), reviewed_at: '', sent_at: '', notes: 'Revisar manualmente antes de enviar.', outreach_status: 'Draft generated', updated_at: new Date().toISOString() } }];
